function ticketTable(tickets,compact=false){return `<div class="table-wrap"><table><thead><tr><th>الطلب</th><th>الحالة</th>${!compact?'<th>الجهة المسؤولة</th><th>الأولوية</th>':''}<th>تاريخ التقديم</th><th><span class="sr-only">التفاصيل</span></th></tr></thead><tbody>${tickets.length?tickets.map(t=>`<tr><td><button class="row-link" data-action="ticket-detail" data-id="${t.id}"><span class="ticket-subject">${e(t.subject)}</span><span class="ticket-id">${t.id}</span></button></td><td>${badge(t.status)}</td>${!compact?`<td>${serviceBy(t.service).unit}</td><td>${e(t.priority)}</td>`:''}<td style="color:#8b9b8a;font-size:12px">${shortDate(t.created)}</td><td><button class="arrow-button" data-action="ticket-detail" data-id="${t.id}" aria-label="تفاصيل ${e(t.subject)}">${icon('chevronLeft')}</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty" style="border:0">${icon('search')}<strong>لم نجد طلبات مطابقة</strong><p>جرّب تغيير البحث أو التصفية.</p><button class="btn secondary small" data-action="clear-ticket-filters">مسح التصفية</button></div></td></tr>`}</tbody></table></div>`;}
function miniInitiative(item){return `<div class="mini-initiative"><div class="mini-top"><button class="mini-title" data-action="initiative-detail" data-id="${item.id}"><span class="mini-mark">${icon(item.icon)}</span>${e(item.title)}</button><span class="mini-pct">${pct(item)}%</span></div><div class="progress-track" role="progressbar" aria-label="إنجاز ${e(item.title)}" aria-valuenow="${pct(item)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${pct(item)}%"></div></div><div class="mini-meta"><span>${item.tasks.filter(t=>t[1]).length} من ${item.tasks.length} مهام</span><span>${shortDate(item.due)}</span></div></div>`;}
function renderOverview(){const greet=role==='admin'?'أهلًا بكم في بوابة الكلية':role==='student'?'أهلًا بك، رحلة أسهل تبدأ هنا':role==='faculty'?'أهلًا بك في مساحتك الأكاديمية':'أهلًا بك في مساحة العمل';main.innerHTML=heading(greet,'خدماتك، معرفتك، ومبادراتك… أقرب إليك.',`<span class="date-label">${icon('calendar')}${fullDate(now())}</span>${newButton()}`)+`<section class="hero"><div class="hero-copy"><span class="hero-tag">${icon('sparkles')} مبادرة التحول الرقمي</span><h2>كل خدمات الكلية، في مكان واحد.</h2><p>من أول طلب إلى آخر محاضرة؛ تجربة رقمية تجمع منسوبي الكلية، وتحوّل المبادرات إلى أثر ملموس.</p><div class="hero-actions"><button class="btn light" data-action="new-ticket">تقديم طلب ${icon('arrowLeft')}</button><a class="btn outline-light" href="#library">استكشف المكتبة</a></div></div>${heroArt()}</section>`+mainMetrics()+`<div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>${isStaff()?'أحدث الطلبات':'أحدث طلباتي'}</h2><p>متابعة مستمرة من التقديم حتى الإنجاز</p></div><a class="text-button" href="#tickets">عرض الكل ${icon('arrowLeft')}</a></div>${ticketTable(visibleTickets().slice(0,4),true)}<div class="panel-bottom">${icon('shield')} لكل طلب جهة مسؤولة وسجل متابعة واضح</div></section><section class="panel"><div class="panel-header"><div><h2>المبادرات النشطة</h2><p>خطوات صغيرة، أثر مستدام</p></div><a class="text-button" href="#initiatives">التفاصيل ${icon('arrowLeft')}</a></div><div class="mini-initiatives">${data.initiatives.filter(i=>pct(i)<100).slice(0,3).map(miniInitiative).join('')}</div><div class="panel-bottom">${icon('target')} مؤشرات محسوبة من مهام النموذج</div></section></div><div class="section-heading"><div><h2>جديد المكتبة الأكاديمية</h2><p>المعرفة مرتبة، والوصول أسهل</p></div><a class="text-button" href="#library">تصفح المكتبة ${icon('arrowLeft')}</a></div><section class="library-grid dashboard-library">${data.resources.slice(0,3).map(resourceCard).join('')}</section>`;}
function renderTickets(){const tickets=visibleTickets();main.innerHTML=heading('التذاكر والطلبات',isStaff()?'إدارة الطلبات وتوجيهها ومتابعة استجابة الجهات المسؤولة.':'قدّم طلبك وتابع كل خطوة حتى إتمام الخدمة.',`<button class="btn secondary export-btn" data-action="export-tickets">${icon('download')} تصدير</button>${newButton()}`)+`<div class="service-strip">${services.slice(0,3).map(s=>`<button class="service-card" data-action="new-ticket" data-service="${s.id}"><span class="service-icon">${icon(s.icon)}</span><span><strong>${e(s.name)}</strong><small>${e(s.unit)} · ${e(s.time)}</small></span>${icon('arrowLeft')}</button>`).join('')}</div><div class="tabs" aria-label="تصفية الطلبات حسب الحالة">${[['all','جميع الطلبات'],...Object.entries(statusNames)].map(([key,title])=>`<button class="tab ${ticketFilter===key?'active':''}" data-action="ticket-filter" data-filter="${key}" aria-pressed="${ticketFilter===key}">${title}<span>${key==='all'?tickets.length:tickets.filter(t=>t.status===key).length}</span></button>`).join('')}</div><div class="filters"><label class="search-field">${icon('search')}<input id="ticket-search" type="search" value="${e(ticketSearch)}" placeholder="ابحث برقم الطلب أو عنوانه…" aria-label="البحث في الطلبات"></label><select class="filter-select" id="service-filter" aria-label="نوع الخدمة"><option value="all">جميع الخدمات</option>${services.map(s=>`<option value="${s.id}" ${serviceFilter===s.id?'selected':''}>${e(s.name)}</option>`).join('')}</select></div><section class="panel" id="ticket-results"></section><div class="demo-source">${icon('info')} أزمنة الخدمة تقديرية للعرض، وتُعتمد مع الجهات المسؤولة عند التشغيل الرسمي.</div>`;renderTicketResults();}
function renderTicketResults(){const q=ticketSearch.trim().toLowerCase();const tickets=visibleTickets().filter(t=>(ticketFilter==='all'||t.status===ticketFilter)&&(serviceFilter==='all'||t.service===serviceFilter)&&(!q||(t.subject+' '+t.id+' '+t.name).toLowerCase().includes(q)));$('#ticket-results').innerHTML=ticketTable(tickets);}
function newTicket(selected='certificate'){if(!role)return;const s=serviceBy(selected);openDialog(dialogHeader('طلب جديد','ابدأ طلبك؛ وسيُوجَّه إلى الجهة المسؤولة عن الخدمة.')+`<form id="ticket-form"><div class="dialog-body"><div class="service-info" id="service-info">${icon('info')} ${e(s.unit)} · زمن الإنجاز التقديري: ${e(s.time)}</div><div id="form-error"></div><div class="form-grid"><div class="field"><label for="ticket-service">الخدمة المطلوبة <span class="required">*</span></label><select id="ticket-service" name="service" required>${services.map(x=>`<option value="${x.id}" ${selected===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></div><div class="field"><label for="ticket-priority">الأولوية</label><select id="ticket-priority" name="priority"><option>عادية</option><option>مرتفعة</option></select></div><div class="field full"><label for="ticket-subject">عنوان الطلب <span class="required">*</span></label><input id="ticket-subject" name="subject" required maxlength="100" value="${e(s.name)}" placeholder="عنوان مختصر يوضح طلبك"></div><div class="field full"><label for="ticket-description">تفاصيل الطلب <span class="required">*</span></label><textarea id="ticket-description" name="description" required minlength="10" maxlength="2000" placeholder="اكتب تفاصيل طلبك لمساعدة الفريق على خدمتك…"></textarea><small>١٠ أحرف على الأقل. استخدم معلومات تجريبية أثناء العرض.</small></div><div class="field full"><label for="ticket-attachment">إرفاق ملف (اختياري)</label><div class="attachment"><input id="ticket-attachment" type="file" accept=".pdf,.png,.jpg,.jpeg" name="attachment"></div><small>PDF أو صورة، حتى ١ ميجابايت. يُحفظ محليًا في هذا المتصفح.</small></div></div></div><div class="dialog-footer"><small>التقديم باسم: ${roleNames[role]}</small><button class="btn" type="submit">إرسال الطلب ${icon('send')}</button></div></form>`);}
function fileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('file read'));reader.readAsDataURL(file);});}
async function submitTicket(form){const f=new FormData(form),subject=String(f.get('subject')).trim(),description=String(f.get('description')).trim();if(subject.length<3||description.length<10){$('#form-error').innerHTML='<div class="form-error">اكتب عنوانًا من ٣ أحرف على الأقل، وتفاصيل من ١٠ أحرف على الأقل.</div>';return;}const file=$('#ticket-attachment').files[0];if(file&&(file.size>1024*1024||!['application/pdf','image/png','image/jpeg'].includes(file.type))){$('#form-error').innerHTML='<div class="form-error">اختر ملف PDF أو صورة PNG أو JPG بحجم لا يتجاوز ١ ميجابايت.</div>';return;}const submit=$('button[type="submit"]',form);submit.disabled=true;try{const created=now();const ticket={id:`MED-2026-${data.nextTicket}`,subject,description,service:String(f.get('service')),priority:String(f.get('priority')),assignee:defaultAssignee(String(f.get('service')),roleOwners[role]),owner:roleOwners[role],name:roleNames[role],status:'new',created,attachment:file?{name:file.name,data:await fileData(file),type:file.type}:null,replies:[],history:[{status:'new',time:created}]};if(update(next=>{next.tickets.unshift(ticket);next.nextTicket++;})){closeDialog();ticketFilter='all';ticketSearch='';serviceFilter='all';go('tickets');toast(`تم إنشاء طلبك بنجاح · ${ticket.id}`);ticketDetail(ticket.id);}}catch{toast('تعذر قراءة الملف؛ أعد المحاولة.');}finally{submit.disabled=false;}}
function ticketDetail(id){const t=visibleTickets().find(t=>t.id===id);if(!t){toast('هذا الطلب غير متاح في منظور العرض الحالي.');return;}const level=t.status==='done'?3:t.status==='new'?0:t.status==='waiting'?2:1;openDialog(dialogHeader('تفاصيل الطلب','كل خطوة موثقة، والتواصل مع الفريق في مكان واحد.')+`<div class="dialog-body"><div class="ticket-detail-head"><span class="ticket-id">${t.id}</span>${badge(t.status)}</div><h3 class="detail-subject">${e(t.subject)}</h3><div class="detail-meta"><div><small>الجهة المسؤولة</small><strong>${serviceBy(t.service).unit}</strong></div><div><small>مقدم الطلب</small><strong>${e(t.name)}</strong></div><div><small>تاريخ التقديم</small><strong>${fullDate(t.created)}</strong></div></div><div class="ticket-assignee">${icon('user')} المحال إليه: ${assigneeName(t.assignee)}${role==='admin'?`<button class="text-button" data-action="assign-ticket" data-id="${t.id}">تغيير الإحالة</button>`:''}</div><div class="timeline">${['تم الاستلام','قيد المعالجة','استكمال المتابعة','تم الإنجاز'].map((label,i)=>`<div class="timeline-step ${i<=level?'complete':''}"><span class="timeline-dot">${i<=level?icon('check'):i+1}</span>${label}</div>`).join('')}</div><div class="detail-description">${e(t.description)}</div>${t.attachment?`<div class="file-list">${icon('clip')} <button class="text-button" data-action="download-attachment" data-id="${t.id}">${e(t.attachment.name)} ${icon('download')}</button></div>`:''}<h3 class="detail-section-title">المحادثة وسجل المتابعة</h3><div class="reply"><div class="reply-top"><strong>النظام</strong><span>${dateTime(t.created)}</span></div><p>تم استلام الطلب وتوجيهه إلى ${serviceBy(t.service).unit}.</p></div>${t.replies.map(r=>`<div class="reply ${r.staff?'staff':''}"><div class="reply-top"><strong>${e(r.author)}</strong><span>${dateTime(r.time)}</span></div><p>${e(r.text)}</p></div>`).join('')}${t.status!=='done'?`<form class="reply-form" id="reply-form" data-id="${id}"><input name="reply" required maxlength="1000" aria-label="إضافة رد" placeholder="${canManageTicket(t)?'أضف ردًا من فريق الخدمة…':'أضف توضيحًا أو استفسارًا…'}"><button class="btn small" type="submit" aria-label="إرسال الرد">${icon('send')}</button></form>`:'<div class="service-info">'+icon('checkCircle')+' اكتمل هذا الطلب. يمكنك تقديم طلب جديد عند الحاجة.</div>'}${canManageTicket(t)?`<div class="staff-controls"><label for="ticket-status">إدارة الطلب · ${roles[role]}</label><div><select id="ticket-status">${Object.entries(statusNames).map(([key,label])=>`<option value="${key}" ${t.status===key?'selected':''}>${label}</option>`).join('')}</select><button class="btn small" data-action="update-ticket" data-id="${id}">حفظ الحالة</button></div></div>`:''}<details class="demo-source" style="display:block"><summary>عرض سجل تغيّر الحالة (${t.history.length})</summary>${t.history.map(h=>`<div style="padding:5px 10px">${statusNames[h.status]} · ${dateTime(h.time)}</div>`).join('')}</details></div><div class="dialog-footer"><small>الأولوية: ${e(t.priority)} · ${serviceBy(t.service).name}</small><button class="btn secondary small" data-action="close">إغلاق</button></div>`);}
function art(type){const shapes={anatomy:'<circle cx="47" cy="19" r="11"/><path d="M47 31v43M27 43l20-9 20 9M47 74 31 97m16-23 16 23M27 43l-9 25m49-25 9 25M34 40v24h26V40M38 48h18m-18 7h18"/>',physiology:'<path d="M24 38c-15-22 16-35 25-14 12-20 40-7 24 16L49 77z"/><path d="M9 48h20l7-16 13 34 10-23 7 5h19"/>',biochem:'<path d="m29 12 23 14v27L29 67 6 53V26zm23 14 23-14 23 14v27L75 67 52 53M29 67v26m-23-40L0 64m75 3v26"/><circle cx="29" cy="12" r="4"/><circle cx="52" cy="26" r="4"/><circle cx="52" cy="53" r="4"/><circle cx="29" cy="67" r="4"/>',pathology:'<circle cx="48" cy="51" r="36"/><circle cx="48" cy="51" r="13"/><circle cx="29" cy="37" r="3"/><circle cx="65" cy="67" r="4"/><path d="M34 72q10 8 20 0M64 31l7 7M20 54l7 2"/>',surgery:'<path d="m18 17 60 70m-59 0 59-70M43 43 29 62m31-19 11 13"/><circle cx="17" cy="87" r="11"/><circle cx="79" cy="87" r="11"/><path d="m18 17 9-9 21 26m30-17-9-9-21 26"/>',clinical:'<path d="M24 11v23c0 28 45 28 45 0V11M17 11h14m31 0h14M47 56v13c0 26 37 26 37 0v-6"/><circle cx="84" cy="55" r="10"/><circle cx="84" cy="55" r="4"/>'};return `<svg class="art" viewBox="0 0 100 110" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[type]||shapes.clinical}</svg>`;}
function resourceCard(r){const saved=data.bookmarks.includes(r.id);return `<article class="resource-card"><div class="resource-cover ${r.type}"><div class="cover-text"><span>${e(r.course)}</span><strong>${e(r.english)}</strong></div>${art(r.type)}<span class="file-tag">PDF · ${r.custom?'UPLOADED':'4 SLIDES'}</span><button class="bookmark ${saved?'saved':''}" data-action="bookmark" data-id="${r.id}" aria-label="${saved?'إزالة من المحفوظات':'حفظ'} ${e(r.title)}" aria-pressed="${saved}">${icon('bookmark')}</button></div><div class="resource-body"><div class="resource-kicker">${years[r.year-1]} · ${e(r.course)}</div><h3>${e(r.title)}</h3><div class="resource-meta"><span>${icon('user')}${e(r.owner)}</span><span>${icon('calendar')}${shortDate(r.updated)}</span></div></div><div class="resource-footer"><span>${r.custom?'ملف مرفوع للتجربة':'محتوى توضيحي للعرض'}</span><div class="resource-actions"><button class="text-button" data-action="resource-preview" data-id="${r.id}">معاينة ${icon('arrowLeft')}</button><button class="icon-button" data-action="resource-download" data-id="${r.id}" aria-label="تنزيل ${e(r.title)}">${icon('download')}</button></div></div></article>`;}
function renderLibrary(){const courses=[...new Set(data.resources.map(r=>r.course))];main.innerHTML=heading('مكتبة السلايدات','مقرراتك ومحاضراتك، مرتبة حسب السنة والمادة.',canUpload()?`<button class="btn" data-action="upload-resource">${icon('upload')} إضافة ملف</button>`:`<span class="date-label">${icon('book')}${data.resources.length} ملفات متاحة</span>`)+`<div class="filters"><label class="search-field">${icon('search')}<input id="resource-search" type="search" value="${e(resourceSearch)}" placeholder="ابحث عن محاضرة أو مقرر…" aria-label="البحث في مكتبة السلايدات"></label><select class="filter-select" id="year-filter" aria-label="السنة الدراسية"><option value="all">جميع السنوات</option>${years.map((y,i)=>`<option value="${i+1}" ${String(yearFilter)===String(i+1)?'selected':''}>${y}</option>`).join('')}</select><select class="filter-select" id="course-filter" aria-label="المقرر"><option value="all">جميع المقررات</option>${courses.map(c=>`<option ${courseFilter===c?'selected':''}>${e(c)}</option>`).join('')}</select><button class="filter-toggle ${onlySaved?'active':''}" data-action="saved-filter" aria-pressed="${onlySaved}">${icon('bookmark')} المحفوظات</button></div><div id="library-results"></div><div class="demo-source">${icon('info')} الملفات المرفقة أمثلة توضيحية من أربع شرائح، وليست سلايدات مقررات فعلية أو محتوى دراسيًا معتمدًا.</div>`;renderLibraryResults();}
function renderLibraryResults(){const q=resourceSearch.trim().toLowerCase();const resources=data.resources.filter(r=>(yearFilter==='all'||String(r.year)===yearFilter)&&(courseFilter==='all'||r.course===courseFilter)&&(!onlySaved||data.bookmarks.includes(r.id))&&(!onlyMine||r.ownerId===roleOwners[role])&&(!q||(r.title+' '+r.course+' '+r.english).toLowerCase().includes(q)));$('#library-results').innerHTML=`<div class="results-count">${resources.length} ملفات ${onlySaved?'في المحفوظات':'متاحة'}</div><div class="library-grid">${resources.length?resources.map(resourceCard).join(''):`<div class="empty">${icon(onlySaved?'bookmark':'search')}<strong>${onlySaved?'لا توجد ملفات محفوظة تطابق اختيارك':'لم نجد ملفات مطابقة'}</strong><p>جرّب تغيير السنة أو المقرر أو كلمة البحث.</p><button class="btn secondary small" data-action="clear-resource-filters">عرض جميع الملفات</button></div>`}</div>`;}
function resourcePreview(id,page=0){const r=data.resources.find(x=>x.id===id);if(!r)return;if(r.custom){openDialog(dialogHeader(e(r.title),'ملف PDF مرفوع محليًا للتجربة')+`<div class="dialog-body"><p class="guide-intro">هذا الملف محفوظ في متصفحك. افتحه في عارض PDF لمعاينة محتواه.</p><button class="btn" data-action="resource-open" data-id="${r.id}">${icon('external')} فتح ملف PDF</button></div><div class="dialog-footer"><small>${years[r.year-1]} · ${e(r.course)}</small><button class="btn" data-action="resource-download" data-id="${r.id}">${icon('download')} تنزيل الملف</button></div>`);return;}previewPage=page;const slides=courseSlides[r.type],slide=slides[page];openDialog(dialogHeader(e(r.title),`${years[r.year-1]} · ${e(r.course)}`)+`<div class="dialog-body"><div class="preview-slide"><div class="slide-kicker">COLLEGE OF MEDICINE · DEMO LIBRARY</div><h3>${e(slide[0])}</h3><p style="white-space:pre-line">${e(slide[1])}</p><div class="slide-bottom"><span>DEMONSTRATION MATERIAL</span><span>${page+1} / ${slides.length}</span></div></div><div class="slide-controls"><button class="icon-button" data-action="slide-prev" data-id="${r.id}" aria-label="الشريحة السابقة" ${page===0?'disabled':''}>${icon('chevronRight')}</button><span>الشريحة ${page+1} من ${slides.length}</span><button class="icon-button" data-action="slide-next" data-id="${r.id}" aria-label="الشريحة التالية" ${page===slides.length-1?'disabled':''}>${icon('chevronLeft')}</button></div><div class="preview-caption">هذا ملف توضيحي لتجربة المكتبة. تُستبدل به سلايدات المقرر بعد اعتمادها من أصحاب المحتوى.</div></div><div class="dialog-footer"><small>٤ شرائح · PDF · نسخة تجريبية</small><button class="btn" data-action="resource-download" data-id="${r.id}">${icon('download')} تنزيل السلايدات</button></div>`,true);}
function uploadResource(){if(!canUpload())return;openDialog(dialogHeader('إضافة ملف للمكتبة','جرّب تنظيم ملف PDF ضمن السنة والمقرر المناسبين.')+`<form id="resource-form"><div class="dialog-body"><div id="form-error"></div><div class="form-grid"><div class="field full"><label for="resource-title">عنوان المحاضرة <span class="required">*</span></label><input id="resource-title" name="title" required maxlength="100" placeholder="مثال: مقدمة في التشريح"></div><div class="field"><label for="resource-year">السنة الدراسية</label><select id="resource-year" name="year">${years.map((y,i)=>`<option value="${i+1}">${y}</option>`).join('')}</select></div><div class="field"><label for="resource-course">المقرر <span class="required">*</span></label><input id="resource-course" name="course" required maxlength="60" placeholder="اسم المقرر"></div><div class="field full"><label for="resource-file">ملف PDF <span class="required">*</span></label><div class="attachment"><input id="resource-file" name="file" type="file" accept=".pdf,application/pdf" required></div><small>حتى ٢ ميجابايت. الملف محفوظ محليًا في هذا المتصفح لأغراض العرض.</small></div></div></div><div class="dialog-footer"><small>استخدم ملفًا تجريبيًا أو محتوى مصرحًا لك برفعه.</small><button class="btn" type="submit">${icon('upload')} إضافة للمكتبة</button></div></form>`);}
async function submitResource(form){if(!canUpload())return;const f=new FormData(form),file=$('#resource-file').files[0];if(!file||file.type!=='application/pdf'||file.size>2*1024*1024){$('#form-error').innerHTML='<div class="form-error">اختر ملف PDF لا يتجاوز حجمه ٢ ميجابايت.</div>';return;}const title=String(f.get('title')).trim(),course=String(f.get('course')).trim();if(!title||!course)return;if(role==='faculty'&&!facultyCourses().includes(course)){toast('يمكنك رفع السلايدات ضمن المقررات المسندة إليك فقط.');return;}const submit=$('button[type="submit"]',form);submit.disabled=true;try{const item={id:'r'+Date.now(),title,course,year:Number(f.get('year')),english:'Course Lecture',type:'clinical',owner:roleNames[role],ownerId:roleOwners[role],updated:now(),custom:true,file:await fileData(file),filename:file.name};if(update(next=>next.resources.unshift(item))){closeDialog();resourceSearch='';yearFilter='all';courseFilter='all';onlySaved=false;go('library');toast('تمت إضافة الملف للمكتبة في هذا المتصفح.');}}catch{toast('تعذر قراءة الملف؛ أعد المحاولة.');}finally{submit.disabled=false;}}
function resourceDownload(id,open=false){const r=data.resources.find(x=>x.id===id);if(!r)return;let url=r.custom?r.file:`assets/slides/${r.type}.pdf`;if(open){if(r.custom){const raw=atob(r.file.split(',')[1]),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));setTimeout(()=>URL.revokeObjectURL(url),60000);}const win=window.open('','_blank');if(win){win.opener=null;win.location=url;}return;}const a=document.createElement('a');a.href=url;a.download=r.filename||`demo-${r.type}.pdf`;document.body.append(a);a.click();a.remove();toast('تم بدء تنزيل الملف '+(r.custom?'المرفوع.':'التوضيحي.'));}
function renderInitiatives(){const tasks=data.initiatives.flatMap(i=>i.tasks);main.innerHTML=heading('متابعة المبادرات','رؤية موحدة للأهداف والمهام والنتائج، من الفكرة إلى الأثر.',role==='admin'?`<button class="btn" data-action="new-initiative">${icon('plus')} مبادرة جديدة</button>`:'')+metrics([{label:'إجمالي المبادرات',value:data.initiatives.length,icon:'flag',sub:'مبادرات توضيحية قابلة للتجربة'},{label:'قيد التنفيذ',value:data.initiatives.filter(i=>initiativeState(i)==='active').length,icon:'target',sub:'متابعة مباشرة للمهام'},{label:'تحتاج متابعة',value:data.initiatives.filter(i=>initiativeState(i)==='late').length,icon:'clock',sub:'تجاوزت الموعد المحدد',subicon:'clock'},{label:'المهام المنجزة',value:`${tasks.filter(t=>t[1]).length}<small> / ${tasks.length}</small>`,icon:'checkCircle',sub:'النسبة تتحدث عند إتمام المهام'}])+`<div class="tabs">${[['all','جميع المبادرات'],['active','قيد التنفيذ'],['late','تحتاج متابعة'],['done','مكتملة']].map(([key,label])=>`<button class="tab ${initiativeFilter===key?'active':''}" data-action="initiative-filter" data-filter="${key}" aria-pressed="${initiativeFilter===key}">${label}</button>`).join('')}</div><div class="initiative-grid">${data.initiatives.filter(i=>initiativeFilter==='all'||initiativeState(i)===initiativeFilter).map(initiativeCard).join('')||'<div class="empty">'+icon('flag')+'<strong>لا توجد مبادرات في هذه الحالة</strong><p>اختر جميع المبادرات لعرض بقية النتائج.</p></div>'}</div>`;}
function initiativeCard(i){return `<article class="initiative-card"><div class="initiative-card-top"><span class="initiative-symbol">${icon(i.icon)}</span>${initStatus(i)}</div><h3>${e(i.title)}</h3><p>${e(i.description)}</p><div class="initiative-owner">${icon('users')}${e(i.owner)}</div><div class="initiative-progress"><span>إنجاز المهام</span><strong>${pct(i)}%</strong></div><div class="progress-track" role="progressbar" aria-label="إنجاز ${e(i.title)}" aria-valuenow="${pct(i)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${pct(i)}%"></div></div><div class="initiative-card-footer"><span>${icon('calendar')} الموعد: ${shortDate(i.due)}</span><button class="text-button" data-action="initiative-detail" data-id="${i.id}">عرض المهام ${icon('arrowLeft')}</button></div></article>`;}
function initiativeDetail(id){const i=data.initiatives.find(x=>x.id===id);if(!i)return;openDialog(dialogHeader(e(i.title),e(i.description))+`<div class="dialog-body"><div class="ticket-detail-head">${initStatus(i)}<span style="font-size:12.5px;color:var(--muted)">الموعد: ${fullDate(i.due)}</span></div><div class="initiative-owner">${icon('users')}${e(i.owner)}</div><div class="initiative-progress"><span>إنجاز المهام</span><strong>${pct(i)}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${pct(i)}%"></div></div><h3 class="detail-section-title">خطة العمل</h3><div class="task-list">${i.tasks.map(([title,done],index)=>`<label class="task-row ${done?'done':''}"><input type="checkbox" data-task-index="${index}" data-initiative-id="${id}" ${done?'checked':''} ${!isStaff()?'disabled':''}><span><span class="task-text">${e(title)}</span><small>${e(i.owner)}</small></span><span class="task-status">${done?'مكتملة':'قيد المتابعة'}</span></label>`).join('')}</div><div class="service-info">${icon('info')}${isStaff()?'غيّر حالة مهمة لتجربة تحديث المؤشرات تلقائيًا.':'يمكن تحديث المهام من منظور الإدارة أو الموظف في هذا النموذج.'}</div><div class="field"><label for="initiative-due">الموعد المستهدف</label><input id="initiative-due" type="date" value="${i.due}" ${!isStaff()?'disabled':''}></div></div><div class="dialog-footer"><small>النسبة = عدد المهام المكتملة ÷ إجمالي المهام</small>${isStaff()?`<button class="btn" data-action="save-initiative-date" data-id="${id}">حفظ الموعد</button>`:'<button class="btn secondary small" data-action="close">إغلاق</button>'}</div>`);}
function newInitiative(){if(role!=='admin')return;openDialog(dialogHeader('مبادرة جديدة','حدد الهدف والمسؤول وخطة العمل الأولية.')+`<form id="initiative-form"><div class="dialog-body"><div class="form-grid"><div class="field full"><label for="initiative-title">اسم المبادرة <span class="required">*</span></label><input id="initiative-title" name="title" required maxlength="100"></div><div class="field full"><label for="initiative-description">الهدف <span class="required">*</span></label><textarea id="initiative-description" name="description" required maxlength="500"></textarea></div><div class="field"><label for="initiative-owner">الفريق المسؤول <span class="required">*</span></label><input id="initiative-owner" name="owner" required maxlength="80"></div><div class="field"><label for="new-initiative-due">الموعد المستهدف <span class="required">*</span></label><input id="new-initiative-due" name="due" type="date" required></div><div class="field full"><label for="initiative-tasks">المهام، كل مهمة في سطر <span class="required">*</span></label><textarea id="initiative-tasks" name="tasks" required maxlength="1500" placeholder="حصر الاحتياج&#10;إعداد الخطة&#10;تنفيذ التجربة&#10;قياس النتائج"></textarea><small>حتى ١٠ مهام في هذا النموذج.</small></div></div></div><div class="dialog-footer"><small>تُضاف المبادرة ببيانات تجريبية في هذا المتصفح.</small><button class="btn" type="submit">إضافة المبادرة ${icon('plus')}</button></div></form>`);}
function renderReports(){const tickets=visibleTickets(),completed=tickets.filter(t=>t.status==='done').length,tasks=data.initiatives.flatMap(i=>i.tasks);main.innerHTML=heading('التقارير والمؤشرات','صورة واضحة تساعد على المتابعة واتخاذ القرار.',`<button class="btn secondary export-btn" data-action="print">${icon('file')} طباعة</button><button class="btn" data-action="export-report">${icon('download')} تصدير التقرير</button>`)+mainMetrics()+`<div class="reports-grid"><section class="panel"><div class="panel-header"><div><h2>توزيع حالات الطلبات</h2><p>${isStaff()?'جميع طلبات النموذج':'طلباتك في هذا المنظور'}</p></div>${icon('chart')}</div><div class="report-body">${Object.entries(statusNames).map(([key,label])=>{const count=tickets.filter(t=>t.status===key).length;return `<div class="chart-row"><span>${label}</span><div class="chart-bar"><i style="width:${tickets.length?count/tickets.length*100:0}%;background:${key==='new'?'#91a9c2':key==='progress'?'#b5a06a':key==='waiting'?'#b09ab3':'#73a382'}"></i></div><strong>${count}</strong></div>`;}).join('')}<div class="report-note">تتحدث القيم تلقائيًا عند تقديم الطلبات أو تغيير حالتها.</div></div></section><section class="panel"><div class="panel-header"><div><h2>ملخص الأداء</h2><p>مؤشرات محسوبة من بيانات التجربة</p></div>${icon('target')}</div><div class="report-body"><div class="report-stat"><span>نسبة إغلاق الطلبات</span><strong>${tickets.length?Math.round(completed/tickets.length*100):0}%</strong></div><div class="report-stat"><span>مهام المبادرات المكتملة</span><strong>${tasks.filter(t=>t[1]).length} / ${tasks.length}</strong></div><div class="report-stat"><span>مبادرات تحتاج متابعة</span><strong>${data.initiatives.filter(i=>initiativeState(i)==='late').length}</strong></div><div class="report-stat"><span>ملفات السلايدات</span><strong>${data.resources.length}</strong></div></div></section></div><div class="section-heading"><h2>تقدم المبادرات</h2></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>المبادرة</th><th>المسؤول</th><th>نسبة الإنجاز</th><th>الموعد</th><th>الحالة</th></tr></thead><tbody>${data.initiatives.map(i=>`<tr><td><button class="row-link" data-action="initiative-detail" data-id="${i.id}">${e(i.title)}</button></td><td>${e(i.owner)}</td><td style="font-family:var(--font)">${pct(i)}%</td><td>${shortDate(i.due)}</td><td>${initStatus(i)}</td></tr>`).join('')}</tbody></table></div></section><div class="prototype-note">جميع الأسماء والطلبات والمؤشرات المعروضة بيانات تجريبية؛ لا تمثل نتائج فعلية للكلية. أزمنة الاستجابة ورضا المستفيدين تُضاف بعد الربط بمصادر بيانات معتمدة.</div>`;}
function downloadCsv(filename,rows){const safeCell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\ufeff'+rows.map(row=>row.map(safeCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('تم تصدير بيانات النموذج بصيغة CSV.');}
function exportTickets(){downloadCsv('colmed-demo-tickets.csv',[['نموذج تجريبي - كلية الطب - جامعة أم القرى'],['رقم الطلب','عنوان الطلب','الخدمة','الحالة','الجهة المسؤولة','الأولوية','تاريخ التقديم'],...visibleTickets().map(t=>[t.id,t.subject,serviceBy(t.service).name,statusNames[t.status],serviceBy(t.service).unit,t.priority,fullDate(t.created)])]);}
function exportReport(){downloadCsv('colmed-demo-report.csv',[['تقرير تجريبي - مبادرة التحول الرقمي'],['تاريخ التقرير',fullDate(now())],['منظور العرض',roles[role]],[],['المؤشر','القيمة'],['إجمالي الطلبات',visibleTickets().length],['الطلبات المكتملة',visibleTickets().filter(t=>t.status==='done').length],['ملفات المكتبة',data.resources.length],[],['المبادرة','المسؤول','الموعد المستهدف','المهام المكتملة','إجمالي المهام','نسبة الإنجاز'],...data.initiatives.map(i=>[i.title,i.owner,i.due,i.tasks.filter(t=>t[1]).length,i.tasks.length,pct(i)+'%'])]);}
function showGuide(){openDialog(dialogHeader('جولة في نموذج التحول الرقمي','مسار عرض مقترح لد. أحمد مفتي')+`<div class="dialog-body"><p class="guide-intro">نموذج تفاعلي يجمع ثلاث رحلات أساسية في بوابة واحدة. جميع العمليات التالية تجريبية ومحفوظة على جهاز العرض.</p>${[['قدّم طلبًا كطالب','بدّل المنظور إلى الطالب، ثم قدّم طلب استلام وثيقة. ستظهر تذكرة برقم وحالة وسجل متابعة.'],['تابع الطلب كموظف','بدّل إلى الموظف، وافتح الطلب وأضف ردًا وغيّر الحالة إلى قيد المعالجة ثم مكتمل.'],['استعرض المكتبة الأكاديمية','اختر السنة والمقرر، عاين الشرائح، نزّل ملف PDF توضيحيًا، واحفظ محاضرة في المحفوظات.'],['تابع أثر المبادرات','بدّل إلى الإدارة وافتح مبادرة، وأكمل مهمة. شاهد تحديث نسبة الإنجاز والتقرير تلقائيًا.']].map(([title,desc],i)=>`<div class="guide-step"><span class="guide-number">${i+1}</span><div><strong>${title}</strong><p>${desc}</p></div></div>`).join('')}<div class="prototype-note">التبديل بين الأدوار محاكاة للعرض، ويحتاج التشغيل الرسمي إلى دخول جامعي وصلاحيات وربط مع أنظمة الجامعة.</div></div><div class="dialog-footer"><button class="text-button" data-action="reset-demo">${icon('refresh')} إعادة ضبط بيانات العرض</button><button class="btn" data-action="start-tour">ابدأ التجربة ${icon('arrowLeft')}</button></div>`);}
function showNotifications(){const open=visibleTickets().filter(t=>t.status!=='done'),late=data.initiatives.filter(i=>initiativeState(i)==='late');openDialog(dialogHeader('التنبيهات','ملخص المتابعة في بيانات العرض الحالية')+`<div class="dialog-body"><div class="notification">${icon('ticket')}<div><strong>${open.length} طلبات قيد المتابعة</strong><p>تصفح التذاكر لمعرفة الحالة والجهة المسؤولة.</p><button class="text-button" data-action="go-tickets">فتح الطلبات ${icon('arrowLeft')}</button></div></div><div class="notification">${icon('clock')}<div><strong>${late.length} مبادرات تحتاج متابعة</strong><p>تجاوزت موعدها المستهدف، مع وجود مهام غير مكتملة.</p><button class="text-button" data-action="go-initiatives">عرض المبادرات ${icon('arrowLeft')}</button></div></div><div class="notification">${icon('book')}<div><strong>${data.resources.length} ملفات في المكتبة</strong><p>ابحث عن المحاضرات حسب السنة والمقرر.</p></div></div></div><div class="dialog-footer"><small>تنبيهات محسوبة من النموذج، دون إرسال خارجي.</small><button class="btn secondary small" data-action="close">إغلاق</button></div>`);}
function resetDemo(){openDialog(dialogHeader('إعادة ضبط النموذج','تُحذف الطلبات والملفات والتعديلات التي أضفتها في هذا المتصفح.')+`<div class="dialog-body"><p class="guide-intro">ستعود بيانات العرض الأساسية لتتمكن من بدء جولة جديدة. احتفظ بالتقارير أو الملفات التي تحتاجها قبل المتابعة.</p></div><div class="dialog-footer"><button class="btn secondary" data-action="guide">إلغاء</button><button class="btn" data-action="confirm-reset">إعادة ضبط البيانات</button></div>`);}
function closeMenu(){$('#sidebar').classList.remove('open');$('#mobile-overlay').classList.remove('visible');$('#menu-button').setAttribute('aria-expanded','false');}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const {action,id,filter,service}=button.dataset;switch(action){
 case 'close':closeDialog();break;
 case 'new-ticket':newTicket(service);break;
 case 'ticket-detail':ticketDetail(id);break;
 case 'ticket-filter':ticketFilter=filter;renderTickets();break;
 case 'clear-ticket-filters':ticketFilter='all';ticketSearch='';serviceFilter='all';renderTickets();break;
 case 'update-ticket':{const t=visibleTickets().find(t=>t.id===id);if(!t||!canManageTicket(t))return;const value=$('#ticket-status').value;if(t.status===value){toast('حالة الطلب لم تتغير.');return;}if(update(next=>{const item=next.tickets.find(t=>t.id===id);item.status=value;item.history.push({status:value,time:now()});item.replies.push({author:roleNames[role],text:'تم تحديث حالة الطلب إلى: '+statusNames[value]+'.',staff:true,time:now()});})){render();ticketDetail(id);toast('تم تحديث حالة الطلب.');}break;}
 case 'download-attachment':{const t=data.tickets.find(t=>t.id===id);if(t?.attachment){const a=document.createElement('a');a.href=t.attachment.data;a.download=t.attachment.name;a.click();}break;}
 case 'bookmark':if(update(next=>{const index=next.bookmarks.indexOf(id);if(index>=0)next.bookmarks.splice(index,1);else next.bookmarks.push(id);})){if(view==='library')renderLibraryResults();else if(['basic-years','clinical-years'].includes(view))render();else renderOverview();toast(data.bookmarks.includes(id)?'أُضيف الملف إلى محفوظاتك.':'أُزيل الملف من المحفوظات.');}break;
 case 'saved-filter':onlySaved=!onlySaved;renderLibrary();break;
 case 'clear-resource-filters':resourceSearch='';yearFilter='all';courseFilter='all';onlySaved=false;renderLibrary();break;
 case 'resource-preview':resourcePreview(id);break;
 case 'slide-prev':resourcePreview(id,Math.max(0,previewPage-1));break;
 case 'slide-next':resourcePreview(id,Math.min(3,previewPage+1));break;
 case 'resource-download':resourceDownload(id);break;
 case 'resource-open':resourceDownload(id,true);break;
 case 'upload-resource':uploadResource();break;
 case 'initiative-filter':initiativeFilter=filter;renderInitiatives();break;
 case 'initiative-detail':initiativeDetail(id);break;
 case 'new-initiative':newInitiative();break;
 case 'save-initiative-date':{if(!isStaff())return;const due=$('#initiative-due').value;if(!due){toast('حدد الموعد المستهدف.');return;}if(update(next=>{next.initiatives.find(i=>i.id===id).due=due;})){render();initiativeDetail(id);toast('تم حفظ الموعد المستهدف.');}break;}
 case 'export-tickets':exportTickets();break;
 case 'export-report':exportReport();break;
 case 'print':window.print();break;
 case 'guide':showGuide();break;
 case 'reset-demo':resetDemo();break;
 case 'confirm-reset':if(commit(makeSeed())){closeDialog();ticketFilter='all';ticketSearch='';serviceFilter='all';resourceSearch='';yearFilter='all';courseFilter='all';onlySaved=false;initiativeFilter='all';render();toast('عادت بيانات العرض الأساسية.');}break;
 case 'start-tour':closeDialog();enterRole('student','tickets');newTicket();break;
 case 'go-tickets':closeDialog();go('tickets');break;
 case 'go-initiatives':closeDialog();go('initiatives');break;
 }});
document.addEventListener('input',event=>{switch(event.target.id){case 'ticket-search':ticketSearch=event.target.value;renderTicketResults();break;case 'resource-search':resourceSearch=event.target.value;renderLibraryResults();break;}});
document.addEventListener('change',event=>{const target=event.target;switch(target.id){
 case 'role-select':enterRole(target.value);break;
 case 'service-filter':serviceFilter=target.value;renderTicketResults();break;
 case 'year-filter':yearFilter=target.value;renderLibraryResults();break;
 case 'course-filter':courseFilter=target.value;renderLibraryResults();break;
 case 'ticket-service':{const s=serviceBy(target.value);$('#service-info').innerHTML=icon('info')+' '+s.unit+' · زمن الإنجاز التقديري: '+s.time;$('#ticket-subject').value=s.name;break;}
 }if(target.matches('[data-task-index]')){if(!isStaff())return;const id=target.dataset.initiativeId,index=Number(target.dataset.taskIndex),checked=target.checked;if(update(next=>{next.initiatives.find(i=>i.id===id).tasks[index][1]=checked;})){render();initiativeDetail(id);toast(checked?'اكتملت المهمة وتحدثت مؤشرات المبادرة.':'أُعيدت المهمة إلى المتابعة.');}}
});
document.addEventListener('submit',event=>{if(!['ticket-form','reply-form','resource-form','initiative-form'].includes(event.target.id))return;event.preventDefault();const form=event.target;if(form.id==='ticket-form')submitTicket(form);if(form.id==='resource-form')submitResource(form);if(form.id==='reply-form'){const text=String(new FormData(form).get('reply')).trim();if(!text)return;const id=form.dataset.id,ticket=visibleTickets().find(t=>t.id===id);if(!ticket||ticket.status==='done')return;if(update(next=>next.tickets.find(t=>t.id===id).replies.push({author:roleNames[role],text,time:now(),staff:canManageTicket(ticket)}))){ticketDetail(id);toast('أُضيف ردك إلى سجل الطلب.');}}if(form.id==='initiative-form'){if(role!=='admin')return;const f=new FormData(form),tasks=String(f.get('tasks')).split(/\r?\n/).map(t=>t.trim()).filter(Boolean).slice(0,10);if(!tasks.length){toast('أضف مهمة واحدة على الأقل.');return;}const item={id:'i'+Date.now(),title:String(f.get('title')).trim(),description:String(f.get('description')).trim(),owner:String(f.get('owner')).trim(),due:String(f.get('due')),icon:'flag',tasks:tasks.map(t=>[t,false])};if(!item.title||!item.description||!item.owner)return;if(update(next=>next.initiatives.unshift(item))){closeDialog();initiativeFilter='all';go('initiatives');render();toast('أُضيفت المبادرة وخطة العمل.');}}});
$('#guide-button').addEventListener('click',showGuide);
$('#notifications-button').addEventListener('click',showNotifications);
$('#role-hint').addEventListener('click',()=>showRoleEntry());
$('#menu-button').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#mobile-overlay').classList.toggle('visible',open);$('#menu-button').setAttribute('aria-expanded',String(open));});
$('#mobile-overlay').addEventListener('click',closeMenu);
dialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next==='main'){main.focus();return;}view=navItems.some(n=>n[0]===next)?next:'overview';render();closeMenu();window.scrollTo({top:0,behavior:'instant'});});
view=navItems.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'overview';
hydrateIcons();if(!storageAvailable)setTimeout(()=>toast('التخزين المحلي غير متاح؛ قد لا تُحفظ التغييرات بعد إغلاق الصفحة.'),700);
